// server/controllers/todoController.js
import Todo from '../models/Todo.js';

const sendNotFound = (res) => res.status(404).json({ success: false, message: 'Todo not found' });

/** Get todos, optionally filtered by completion, priority, and title text. */
export const getTodos = async (req, res, next) => {
  try {
    const { completed, priority, search } = req.query;
    const query = {};
    if (completed === 'true' || completed === 'false') query.completed = completed === 'true';
    if (priority) query.priority = priority;
    if (search?.trim()) query.title = { $regex: search.trim(), $options: 'i' };
    const todos = await Todo.find(query).sort({ createdAt: -1 });
    res.json({ success: true, count: todos.length, data: todos });
  } catch (error) { next(error); }
};

/** Get one todo by its MongoDB id. */
export const getTodo = async (req, res, next) => {
  try {
    const todo = await Todo.findById(req.params.id);
    if (!todo) return sendNotFound(res);
    res.json({ success: true, data: todo });
  } catch (error) { next(error); }
};

/** Create a todo from validated request data. */
export const createTodo = async (req, res, next) => {
  try {
    const todo = await Todo.create(req.body);
    res.status(201).json({ success: true, data: todo });
  } catch (error) { next(error); }
};

/** Replace editable fields of a todo. */
export const updateTodo = async (req, res, next) => {
  try {
    const todo = await Todo.findByIdAndUpdate(req.params.id, req.body, { new: true, runValidators: true });
    if (!todo) return sendNotFound(res);
    res.json({ success: true, data: todo });
  } catch (error) { next(error); }
};

/** Invert a todo's completed state. */
export const toggleTodo = async (req, res, next) => {
  try {
    const todo = await Todo.findById(req.params.id);
    if (!todo) return sendNotFound(res);
    todo.completed = !todo.completed;
    await todo.save();
    res.json({ success: true, data: todo });
  } catch (error) { next(error); }
};

/** Delete one todo. */
export const deleteTodo = async (req, res, next) => {
  try {
    const todo = await Todo.findByIdAndDelete(req.params.id);
    if (!todo) return sendNotFound(res);
    res.json({ success: true, data: todo });
  } catch (error) { next(error); }
};

/** Delete all completed todos. */
export const deleteCompletedTodos = async (_req, res, next) => {
  try {
    const result = await Todo.deleteMany({ completed: true });
    res.json({ success: true, count: result.deletedCount, data: [] });
  } catch (error) { next(error); }
};
